productos = [
    {"sku": "A1", "categoria": "libros", "precio": 15},
    {"sku": "A2", "categoria": "libros", "precio": 30},
    {"sku": "A3", "categoria": "electronica", "precio": 200},
]

def document_store_query(coleccion, categoria, precio_max):
    return [p for p in coleccion if p["categoria"] == categoria and p["precio"] <= precio_max]

key_value_store = {p["sku"]: p for p in productos}

def key_value_get(kv, clave):
    return kv.get(clave)

resultado_documentos = document_store_query(productos, "libros", 20)
print("document store filtra por campos:", resultado_documentos)

resultado_kv = key_value_get(key_value_store, "A3")
print("key-value solo busca por clave exacta:", resultado_kv)
